7	} from "@motion-studio/shared";
8	import type { AssetCatalog, IAssetCatalogEntry } from "./asset-catalog";
9	import type { IAssetBlobStore, IThumbnailStore, IWaveformStore } from "./asset-storage";
10	import type { IMetadataExtractor } from "./metadata";
11	import { detectAssetType } from "./supported-types";
12	import type { IThumbnailGenerator } from "./thumbnail-generator";
13	import type { IWaveformGenerator } from "./waveform-generator";
14	
15	/** Same generic shape as Export's `IExportEventSink` / History's `IHistoryEventSink`. */
16	export interface IAssetEventSink {
17	  emit<T extends AppEventType>(type: T, payload: AppEventMap[T]): void;
18	}
19	
20	export interface IAssetImportInput {
21	  readonly fileName: string;
22	  readonly mimeType: string;
23	  readonly data: Uint8Array;
24	  readonly tags?: readonly string[];
25	}
26	
27	export interface IAssetImportDependencies {
28	  readonly blobStore: IAssetBlobStore;
29	  readonly catalog: AssetCatalog;
30	  readonly metadataExtractor: IMetadataExtractor;
31	  readonly thumbnailGenerator?: IThumbnailGenerator;
32	  readonly thumbnailStore?: IThumbnailStore;
33	  readonly waveformGenerator?: IWaveformGenerator;
34	  readonly waveformStore?: IWaveformStore;
35	  readonly events?: IAssetEventSink;
36	}
37	
38	/**
39	 * `docs/14-assets/importer.md`'s pipeline: validate -> hash -> store (via
40	 * `IAssetBlobStore`, dedup for free) -> detect type -> metadata ->
41	 * thumbnail -> waveform -> register in catalog -> ready. Runs on the
42	 * caller's thread today — worker wiring is the same "not yet plumbed" gap
43	 * as Export's job runner (Phase 10). Proxy generation
44	 * (`docs/14-assets/overview.md` "Proxy system") is intentionally out of
45	 * Phase 12's scope — not in PLAN.md's checklist.
46	 *
47	 * The content hash *is* the asset id, so re-importing identical bytes
48	 * resolves to the same catalog entry without a separate "look up by hash"
49	 * pass, and without re-running metadata/thumbnail/waveform extraction.
50	 */
51	export async function importAsset(
52	  input: IAssetImportInput,
53	  deps: IAssetImportDependencies,
54	): Promise<IAssetCatalogEntry> {
55	  try {
56	    if (input.data.byteLength === 0) {
57	      throw new Error(`AssetImport: "${input.fileName}" is empty`);
58	    }
59	
60	    const type = detectAssetType(input.fileName, input.mimeType);
61	    if (type === undefined) {
62	      throw new Error(`AssetImport: unsupported type for "${input.fileName}" (${input.mimeType})`);
63	    }
64	
65	    const contentHash = await deps.blobStore.put(input.data);
66	    const assetId = createAssetId(contentHash);
67	
68	    const existing = await deps.catalog.get(assetId);
69	    if (existing) {
70	      return existing;
71	    }
72	
73	    const metadata = await deps.metadataExtractor.extract(input.data, type, input.mimeType);
