      mimeType: "image/png",
      data: new Uint8Array([2]),
    });
    manager.registerReference(used.id, "trackItem-1");

    const unusedList = await manager.listUnused();

    expect(unusedList.map((entry) => entry.id)).toEqual([unused.id]);
  });

